get_tax_settings.code:
var response = await client.TaxSettings.GetTaxSettingsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxSettings = (IReadOnlyDictionary<string, object?>)body["tax_settings"]!;
Console.WriteLine($"{taxSettings["tax_rate_for_customers"]} {taxSettings["prices_in_catalog"]} {taxSettings["tax_message"]}");

put_tax_settings.code:
var response = await client.TaxSettings.PutTaxSettingsAsync(new Dictionary<string, object?>
{
    ["tax_settings"] = new Dictionary<string, object?> { ["tax_message"] = "All prices include GST" },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxSettings = (IReadOnlyDictionary<string, object?>)body["tax_settings"]!;
Console.WriteLine(taxSettings["tax_message"]);

patch_tax_settings.code:
var response = await client.TaxSettings.PatchTaxSettingsAsync(new Dictionary<string, object?>
{
    ["tax_settings"] = new Dictionary<string, object?> { ["is_price_shown_with_tax"] = true },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxSettings = (IReadOnlyDictionary<string, object?>)body["tax_settings"]!;
Console.WriteLine(taxSettings["is_price_shown_with_tax"]);
